                      UID:series-uid\r\n\
                      DTSTAMP:20260101T000000Z\r\n\
                      DTSTART:20260116T020000Z\r\n\
                      DTEND:20260116T030000Z\r\n\
                      RECURRENCE-ID:20260116T000000Z\r\n\
                      SUMMARY:Modified Occurrence\r\n\
